// --- Variables Globales ---
let particles = [];
const NUM_PARTICLES = 100;

// --- Clase Particle ---
class Particle {
    constructor(x, y) {
        this.pos = createVector(x, y);
        this.vel = p5.Vector.random2D().mult(random(0.5, 2));
        this.acc = createVector(0, 0);
        this.lifespan = 255;
    }

    applyForce(force) {
        this.acc.add(force);
    }

    update() {
        this.vel.add(this.acc);
        this.pos.add(this.vel);
        this.acc.mult(0); // Resetear aceleración
        this.lifespan -= 3; // Disminuir vida
    }

    show() {
        stroke(255, this.lifespan); // Color basado en la vida
        strokeWeight(2);
        point(this.pos.x, this.pos.y);
    }
}

// --- Setup ---
function setup() {
    // El canvas se creará automáticamente y ocupará todo el body gracias al CSS
    createCanvas(windowWidth, windowHeight);

    // Inicializar partículas en el centro
    for (let i = 0; i < NUM_PARTICLES; i++) {
        particles.push(new Particle(width / 2, height / 2));
    }
}

// --- Loop Principal ---
function draw() {
    // Fondo semi-transparente para crear un efecto de estela
    background(0, 0, 0, 50); 

    // 1. Aplicar fuerza de atracción/repulsión del ratón
    let mouseForce = p5.Vector.sub(createVector(mouseX, mouseY), createVector(width / 2, height / 2));
    mouseForce.normalize();
    mouseForce.mult(0.01);

    // 2. Actualizar y dibujar partículas
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];

        // Aplicar fuerza del ratón (haciendo que las partículas se muevan hacia el ratón)
        p.applyForce(mouseForce);

        p.update();
        p.show();

        // Remover partículas que han muerto
        if (p.lifespan < 0) {
            particles.splice(i, 1);
        }
    }

    // Si hay espacio, añadir una nueva partícula para mantener el número constante
    if (particles.length < NUM_PARTICLES) {
        particles.push(new Particle(random(width), random(height)));
    }
}

// --- Interacción con el tamaño de la ventana ---
function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}

// Ejecutar la prueba de conexión para confirmar que el entorno está listo
console.log('Sketch p5.js cargado exitosamente.');
